-- Existing owner records and personal ledger IDs are preserved. No identities are seeded.
CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

INSERT OR IGNORE INTO users (id) VALUES ('owner');

CREATE TABLE IF NOT EXISTS user_identities (
  issuer TEXT NOT NULL CHECK (length(trim(issuer)) > 0),
  subject TEXT NOT NULL CHECK (length(trim(subject)) > 0),
  user_id TEXT NOT NULL REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (issuer, subject)
);

ALTER TABLE ledgers ADD COLUMN user_id TEXT NOT NULL DEFAULT 'owner';
CREATE UNIQUE INDEX ledgers_user_idx ON ledgers(user_id);
ALTER TABLE accounts ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';
ALTER TABLE account_currencies ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';
ALTER TABLE transactions ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';
ALTER TABLE imports ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';
ALTER TABLE sync_state ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';
ALTER TABLE plaid_items ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';
ALTER TABLE plaid_accounts ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';
ALTER TABLE recurring_streams ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';
ALTER TABLE recurring_stream_transactions ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';
ALTER TABLE recurring_classifications ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';
ALTER TABLE recurring_sync_state ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';
ALTER TABLE source_profile_hints ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';
ALTER TABLE capture_credentials ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';
ALTER TABLE device_source_scopes ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';
ALTER TABLE alert_event_digests ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';
ALTER TABLE owner_refresh_generations ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';
ALTER TABLE import_chunks ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';
ALTER TABLE import_preview_errors ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';
ALTER TABLE import_duplicate_decisions ADD COLUMN ledger_id TEXT NOT NULL DEFAULT 'personal';

CREATE TABLE lunchflow_accounts_hosted_v21 (
  provider_account_id TEXT NOT NULL,
  account_id TEXT UNIQUE REFERENCES accounts(id),
  ledger_id TEXT NOT NULL DEFAULT 'personal' REFERENCES ledgers(id),
  name TEXT NOT NULL,
  institution TEXT NOT NULL,
  currency TEXT REFERENCES currencies(code),
  kind TEXT CHECK (kind IN ('chequing', 'savings', 'credit')),
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  last_synced_at TEXT,
  last_error TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (ledger_id, provider_account_id)
);
INSERT INTO lunchflow_accounts_hosted_v21 (provider_account_id, account_id, ledger_id, name, institution, currency, kind, enabled, revision, last_synced_at, last_error, created_at, updated_at) SELECT provider_account_id, account_id, ledger_id, name, institution, currency, kind, enabled, revision, last_synced_at, last_error, created_at, updated_at FROM lunchflow_accounts;
DROP TABLE lunchflow_accounts;
ALTER TABLE lunchflow_accounts_hosted_v21 RENAME TO lunchflow_accounts;
CREATE INDEX lunchflow_accounts_ledger_idx ON lunchflow_accounts(ledger_id, enabled, provider_account_id);

CREATE TRIGGER user_identities_no_takeover BEFORE INSERT ON user_identities BEGIN SELECT RAISE(ABORT, 'identity is already assigned') WHERE EXISTS (SELECT 1 FROM user_identities WHERE issuer = NEW.issuer AND subject = NEW.subject AND user_id <> NEW.user_id); END;
CREATE TRIGGER user_identities_immutable_update BEFORE UPDATE ON user_identities BEGIN SELECT RAISE(ABORT, 'identity mappings are immutable'); END;
CREATE TRIGGER user_identities_immutable_delete BEFORE DELETE ON user_identities BEGIN SELECT RAISE(ABORT, 'identity mappings are immutable'); END;
CREATE TRIGGER ledgers_owner_insert BEFORE INSERT ON ledgers BEGIN SELECT RAISE(ABORT, 'ledger owner is required') WHERE NEW.user_id IS NULL OR NOT EXISTS (SELECT 1 FROM users WHERE id = NEW.user_id); END;
CREATE TRIGGER ledgers_owner_update BEFORE UPDATE OF user_id, id ON ledgers BEGIN SELECT RAISE(ABORT, 'ledger ownership is immutable') WHERE NEW.user_id IS NOT OLD.user_id OR NEW.id IS NOT OLD.id; END;
CREATE TRIGGER accounts_ledger_scope_insert BEFORE INSERT ON accounts BEGIN SELECT RAISE(ABORT, 'accounts ledger mismatch') WHERE NOT EXISTS (SELECT 1 FROM ledgers WHERE id = NEW.ledger_id); END;
